// spec: .qa/e2e/specs/match-mutual.md 1.2 · кейс .qa/tests/match-mutual/MATCH-02.md
// @data — не из-за записи, а чтобы сессия free не использовалась параллельно (одноразовый refresh-токен).
// Только чтение: адрес и публичный apikey берутся из запроса приложения под free; гость ничего не создаёт.
import { test, expect } from '../../fixtures';
import { captureApi, asGuest, rpc, restGet } from '../_shared/api';
import { saveSession } from '../_shared/session';

test.describe('Взаимный матч (сервер)', () => {
  test('Без входа swipe, my_matches, messages, matches → 401 @iphone @data @prod-safe (#b76c3b)', async ({ asUser }) => {
    const free = await asUser('free');
    const guestPage = await asUser('guest');
    try {
      const a = await captureApi(free);
      const g = asGuest(a, guestPage);
      const results = [
        ['rpc/swipe', await rpc(g, 'swipe', { p_target: a.userId, p_kind: 'like' })],
        ['rpc/my_matches', await rpc(g, 'my_matches', {})],
        ['GET messages', await restGet(g, 'messages?select=*&limit=1')],
        ['GET matches', await restGet(g, 'matches?select=*&limit=1')],
      ] as const;
      for (const [name, res] of results) {
        expect([401, 403], `${name}: ${res.status()} ${await res.text()}`).toContain(res.status());
      }
    } finally {
      await saveSession(free, 'free');
    }
  });
});
